using ClinicaEsteticaWeb.Models;using ClinicaEsteticaWeb.Services;using Microsoft.AspNetCore.Mvc;
namespace ClinicaEsteticaWeb.Controllers;
public class AccountController:Controller {private readonly WebSessionService _s;public AccountController(WebSessionService s)=>_s=s;[HttpGet]public IActionResult Login(int expired=0){if(expired==1)ViewBag.Error="Sua sessão foi encerrada por inatividade. Faça login novamente.";return View(new LoginViewModel());}[HttpPost][ValidateAntiForgeryToken]public IActionResult Login(LoginViewModel m){if(!ModelState.IsValid)return View(m);var r=_s.Login(HttpContext,m.Login,m.Senha).GetAwaiter().GetResult();if(!r.ok){ViewBag.Error=r.msg;return View(m);}return RedirectToAction("Index","Home");}[HttpPost][ValidateAntiForgeryToken]public IActionResult Logout(){_s.Logout(HttpContext);return RedirectToAction("Login");}}
